'use strict';
const weaponBook={
 sword:{name:'Köz kılıcı',kind:'blade',hands:1,hp:0,speed:0,power:1,attack:0,q:0,icon:'⚔',trait:'Yakın dövüş · 295 temel can',off:'Kalkan tutuşu: +96 can, %3 hasar direnci'},
 dagger:{name:'Gölge hançeri',kind:'blade',hands:1,hp:-18,speed:10,power:1,attack:.08,q:1,icon:'✥',trait:'Çabuk yakın dövüş · −18 can',off:'Çevik tutuş: +%6 saldırı hızı, −48 can'},
 tome:{name:'Kıvılcım tılsımı',kind:'staff',hands:1,hp:-4,speed:3,power:1,attack:.045,q:1,icon:'✧',trait:'Hızlı büyü · −32 can',off:'Büyü odağı: beklemeler %5 kısa, −8 can'},
 bow:{name:'Kül yayı',kind:'bow',hands:2,hp:0,speed:0,power:1,attack:0,q:0,icon:'➶',trait:'Uzun menzil · 260 temel can',off:'İki el gerektirir'},
 staff:{name:'Kor asası',kind:'staff',hands:2,hp:0,speed:0,power:1,attack:0,q:0,icon:'♜',trait:'Alan büyüsü · 270 temel can',off:'İki el gerektirir'}
};
wardrobe.main='sword';wardrobe.off=-1;const weaponChoice={sword:0,dagger:1,tome:1,bow:0,staff:0};
function weaponPair(main,off){const primary=weaponBook[main];return !!primary&&(off===-1||primary.hands===1&&weaponBook[off]?.hands===1);}
const dressedApplyGear=applyGear;
applyGear=function(a,g=wardrobe){const main=weaponBook[g.main]&&weaponBook[g.main].kind===a.kind?g.main:({blade:'sword',bow:'bow',staff:'staff'}[a.kind]);const off=weaponPair(main,g.off)?g.off:-1;dressedApplyGear(a,{...g,main,off});const primary=weaponBook[main];a.weaponPower=primary.power;a.max+=primary.hp;a.speed+=primary.speed;if(off==='sword'){a.max+=12;a.accessory.resist=(a.accessory.resist||0)+.03;}if(off==='dagger'){a.max-=6;a.accessory.attack=(a.accessory.attack||0)+.06;}if(off==='tome'){a.max-=8;a.accessory.cooldown=(a.accessory.cooldown||0)+.05;}a.accessory.attack=(a.accessory.attack||0)+primary.attack;a.hp=a.max;a.gear.main=main;a.gear.off=off;};
const weaponRenderDraft=renderDraft;
renderDraft=function(){const w=weaponBook[wardrobe.main]||weaponBook.sword;chosen=w.kind;equipmentChoice[chosen][0]=weaponChoice[wardrobe.main];weaponRenderDraft();const panel=$('#draft');panel.querySelector('.gear-weapons').innerHTML='<h3>ANA EL <small>Silah saldırıyı ve Q yeteneğini belirler</small></h3><div class="weapon-five">'+Object.entries(weaponBook).map(([id,v])=>'<button data-main="'+id+'" aria-pressed="'+(wardrobe.main===id)+'" class="weapon-card '+(wardrobe.main===id?'active':'')+'"><i>'+v.icon+'</i><b>'+v.name+'</b><small>'+v.hands+' EL · '+v.trait+'</small></button>').join('')+'</div><h3>İKİNCİ EL <small>Tek elli silah pasif etkisini açar</small></h3><div class="weapon-five"><button data-off="-1" aria-pressed="'+(wardrobe.off===-1)+'" class="weapon-card '+(wardrobe.off===-1?'active':'')+'">BOŞ<small>Ek bonus yok</small></button>'+Object.entries(weaponBook).filter(([,v])=>v.hands===1).map(([id,v])=>'<button data-off="'+id+'" '+(w.hands===2?'disabled':'')+' aria-pressed="'+(wardrobe.off===id)+'" class="weapon-card '+(wardrobe.off===id?'active':'')+'"><i>'+v.icon+'</i><b>'+v.name+'</b><small>'+v.off+'</small></button>').join('')+'</div>';panel.querySelector('.weapon-options').innerHTML=equipmentSkills[chosen][0].map((q,i)=>'<button data-q="'+i+'" aria-pressed="'+(weaponChoice[wardrobe.main]===i)+'">Q · '+q[0]+'<small>'+q[1]+'</small></button>').join('');panel.querySelectorAll('[data-q]').forEach(btn=>btn.onclick=()=>{weaponChoice[wardrobe.main]=Number(btn.dataset.q);renderDraft();});panel.querySelector('.draft-head h2').textContent='İki elin. Kendi savaş tarzın.';panel.querySelector('.draft-head p').textContent='Ana silah saldırıyı ve Q’yu belirler. Tek elli silahlar ikinci elde pasif verir; iki elli silahlar her iki eli kaplar.';panel.querySelectorAll('[data-main]').forEach(btn=>btn.onclick=()=>{wardrobe.main=btn.dataset.main;if(weaponBook[wardrobe.main].hands===2)wardrobe.off=-1;renderDraft();});panel.querySelectorAll('[data-off]').forEach(btn=>btn.onclick=()=>{wardrobe.off=btn.dataset.off==='-1'?-1:btn.dataset.off;renderDraft();});};
const weaponConfirm=confirmBuild;
confirmBuild=function(){const w=weaponBook[wardrobe.main]||weaponBook.sword;chosen=w.kind;equipmentChoice[chosen][0]=weaponChoice[wardrobe.main];weaponConfirm();document.querySelectorAll('[data-quick-weapon]').forEach(btn=>btn.classList.toggle('selected',btn.dataset.quickWeapon===wardrobe.main));updateHud();};
const weaponSidebar=$('.loadouts');if(weaponSidebar){weaponSidebar.innerHTML=Object.entries(weaponBook).map(([id,w])=>'<button class="loadout '+(id===wardrobe.main?'selected':'')+'" data-quick-weapon="'+id+'"><span class="weapon">'+w.icon+'</span><span><b>'+w.name+'</b><small>'+w.hands+' el · '+w.trait+'</small></span><span class="dot"></span></button>').join('');document.querySelectorAll('[data-quick-weapon]').forEach(btn=>btn.onclick=()=>{if(phase==='fight'||phase==='between'){notify('Silahı sonraki raundda değiştir.');return;}wardrobe.main=btn.dataset.quickWeapon;wardrobe.off=-1;chosen=weaponBook[wardrobe.main].kind;setKit();updateHud();document.querySelectorAll('[data-quick-weapon]').forEach(x=>x.classList.toggle('selected',x===btn));});}
const weaponHud=updateHud;let displayedWeaponStats='';updateHud=function(){weaponHud();const a=actors[0],w=weaponBook[a?.gear?.main||wardrobe.main];if(w){$('#playerName').textContent=w.name.toLocaleUpperCase('tr-TR');const hp=a?.max??kits[w.kind].hp+w.hp;if(phase==='idle')$('#hpText').textContent=hp+' / '+hp;const key=w.name+':'+hp;if(key!==displayedWeaponStats){const stats=$('#classStats'),description=$('#classDescription');if(stats)stats.innerHTML='<span>CAN '+hp+'</span><span>MENZİL '+(w.kind==='blade'?'YAKIN':'UZAK')+'</span>';if(description)description.textContent=w.trait+(wardrobe.off!==-1?' · İkinci el: '+weaponBook[wardrobe.off].off:'');displayedWeaponStats=key;}}};
const weaponSetKit=setKit;setKit=function(){weaponSetKit();const icon=$('#skills').querySelector?.('.skill .glyph');if(icon)icon.textContent=weaponBook[wardrobe.main]?.icon||'⚔';};
const sidebarTitle=$('.section-label.spaced span');if(sidebarTitle)sidebarTitle.textContent='ANA SİLAHIN';
